var wordVisible = 0;

void closeRow() {
  if (activeSgr.isNotEmpty) row.write('\x1b[0m');
  rows.add(row.toString());
  row
    ..clear()
    ..writeAll(activeSgr);
  col = 0;
}

void writeStyle(String token) {
  row.write(token);
  if (token == '\x1b[0m') {
    activeSgr.clear();
  } else {
    activeSgr.add(token);
  }
}

