if (width <= 0) return [line];
// Skip the ANSI strip on plain-text lines (the common case).
final hasAnsi = line.codeUnits.any((c) => c == 0x1b);
final visible = hasAnsi
    ? tuiTextWidth(line.replaceAll(AnsiMarkdown.ansiSgrPattern, ''))
    : tuiTextWidth(line);
if (visible <= width) return [line];

final rows = <String>[];
final row = StringBuffer();
var col = 0;
// SGR codes active at the current write position (since the last reset).
final activeSgr = <String>[];
// The word being accumulated: whole parts (runs + inline SGR) and its
// visible length. Widths are carried on the parts — the old code
// re-measured every token inside flushWord.
final wordParts = <_WrapPart>[];
var wordVisible = 0;

void closeRow() {
  if (activeSgr.isNotEmpty) row.write('\x1b[0m');
  rows.add(row.toString());
  row
    ..clear()
    ..writeAll(activeSgr);
  col = 0;
}

void writeStyle(String token) {
  row.write(token);
  if (token == '\x1b[0m') {
    activeSgr.clear();
  } else {
    activeSgr.add(token);
  }
}

