// Differential check: OLD wrapAnsiLine (per-char regex tokenizer) vs NEW.
import 'dart:math';
import 'package:flutter_agent_harness/src/cli/ansi_markdown.dart';
import 'package:flutter_agent_harness/src/cli/tui_text_width.dart';
import 'package:test/test.dart';

final _oldRe = RegExp(r'\x1b\[[0-9;]*m|.', unicode: true);

int _oldTokenWidth(String token) {
  if (token.startsWith('\x1b')) return 0;
  if (token.length == 1) {
    final unit = token.codeUnitAt(0);
    if (unit < 0x80) return (unit < 0x20 || unit == 0x7f) ? 0 : 1;
  }
  return tuiTextWidth(token);
}

List<String> oldWrapAnsiLine(String line, int width) {
  if (width <= 0) return [line];
  final hasAnsi = line.codeUnits.any((c) => c == 0x1b);
  final visible = hasAnsi
      ? tuiTextWidth(line.replaceAll(RegExp(r'\x1b\[[0-9;]*m'), ''))
      : tuiTextWidth(line);
  if (visible <= width) return [line];
  final rows = <String>[];
  final row = StringBuffer();
  var col = 0;
  final activeSgr = <String>[];
  final wordTokens = <String>[];
  var wordVisible = 0;
  void closeRow() {
    if (activeSgr.isNotEmpty) row.write('\x1b[0m');
    rows.add(row.toString());
    row
      ..clear()
      ..writeAll(activeSgr);
    col = 0;
  }

  void writeToken(String token, int visibleLen) {
    row.write(token);
    col += visibleLen;
    if (token.startsWith('\x1b')) {
      if (token == '\x1b[0m') {
        activeSgr.clear();
      } else {
        activeSgr.add(token);
      }
    }
  }

  void flushWord() {
    if (wordTokens.isEmpty) return;
    if (wordVisible > width) {
      if (col > 0) closeRow();
      for (final token in wordTokens) {
        final tokenWidth = _oldTokenWidth(token);
        if (col > 0 && !token.startsWith('\x1b') && col + tokenWidth > width) {
          closeRow();
        }
        writeToken(token, tokenWidth);
      }
    } else {
      if (col > 0 && col + wordVisible > width) closeRow();
      for (final token in wordTokens) {
        writeToken(token, _oldTokenWidth(token));
      }
    }
    wordTokens.clear();
    wordVisible = 0;
  }

  for (final match in _oldRe.allMatches(line)) {
    final token = match.group(0)!;
    if (token == ' ') {
      flushWord();
      if (col + 1 <= width) {
        writeToken(token, 1);
      } else {
        closeRow();
      }
      continue;
    }
    wordTokens.add(token);
    if (!token.startsWith('\x1b')) wordVisible += _oldTokenWidth(token);
  }
  flushWord();
  if (col > 0) closeRow();
  return rows;
}

void main() {
  test('differential old vs new over randomized adversarial inputs', () {
    final rng = Random(42);
    const alphabet = [
      'a', 'b', 'Z', '0', ' ', '  ', '\x1b[31m', '\x1b[0m', '\x1b[m',
      '\x1b[1;42m', '\x1b', '\x1b[', '\x1b[31', '[', 'm', ';', '0',
      '✅', '中', '\u{0301}', '\u{200d}', '𐐀', '\t', '\x00', '\x7f',
      'é', '\u{00a0}', '\u{fe0f}', '👨', 'x',
    ];
    var cases = 0;
    for (var iter = 0; iter < 200000; iter++) {
      final len = rng.nextInt(9);
      final sb = StringBuffer();
      for (var j = 0; j < len; j++) {
        sb.write(alphabet[rng.nextInt(alphabet.length)]);
      }
      final line = sb.toString();
      final width = 1 + rng.nextInt(7);
      final a = oldWrapAnsiLine(line, width);
      final b = wrapAnsiLine(line, width);
      cases++;
      if (a.join('\n') != b.join('\n')) {
        fail('MISMATCH width=$width line=${line.codeUnits}\nOLD: ${a.map((r) => r.codeUnits)}\nNEW: ${b.map((r) => r.codeUnits)}');
      }
    }
    print('$cases differential cases passed');
  }, timeout: const Timeout(Duration(minutes: 5)));
}
